/* Dedicated report workspace. Filters affect preview and all exported rows. */
const reportFilters={factory:null,type:'production',period:null,status:'All',source:'All',search:''};
const reportTypes={production:'Production',packaging:'Packaging',facility:'Facility',supplychain:'Supply chain',maintenance:'Maintenance',batches:'Batches',alarms:'Alarms',quality:'Quality / CIP & PAT',workforce:'Workforce',sustainability:'Sustainability',business:'Business KPIs'};
function reportSelection(){return {...reportFilters,factory:reportFilters.factory??state.factory,period:reportFilters.period||$('#period').value||'Today'}}
function collectReportRows(){const f=reportSelection(),oldFactory=state.factory,oldPeriod=$('#period').value,rows=[];try{$('#period').value=f.period;for(const fi of (f.factory<0?factories.map((_,i)=>i):[f.factory])){state.factory=fi;const record=recordFor(fi),section={production:'production',packaging:'production',facility:'facility',supplychain:'supplyChain',maintenance:'assets',batches:'batches',alarms:'alarms',quality:'quality',workforce:'workforce',sustainability:'sustainability',business:'business'}[f.type],supplied=!!record?.[section],source=supplied?(record.origin==='gateway'?'Gateway':'Imported'):'Illustrative',meta={factory:factories[fi].name,period:f.period,source,source_name:supplied?record.source:'Demonstration',observed_at:supplied?record.observedAt:''};let data=[];
 if(['production','packaging'].includes(f.type))data=lineSpecs.map((_,index)=>{const l=lineData(index),actual=record?.production?.lines.some(x=>x.index===index);return {line:index+1,work_order:l.workOrder,product:l.product,target_units:l.target,produced_units:l.output,utilization_percent:l.utilization,status:l.status,...(!actual?{source:'Illustrative',source_name:'Demonstration',observed_at:''}:{})}});
 if(f.type==='facility')data=(record?.facility||[{name:'Cleanroom temperature',value:21.4,unit:'°C',min:20,max:24},{name:'Relative humidity',value:46,unit:'%',min:40,max:55},{name:'Power demand',value:1.24,unit:'MW',min:0,max:1.4}]).map(m=>({measure:m.name,value:m.value,unit:m.unit,minimum:m.min,maximum:m.max,status:m.value>=m.min&&m.value<=m.max?'Within range':'Review'}));
 if(f.type==='supplychain'){const s=record?.supplyChain;data=s?[...s.materials.map(m=>({entity_type:'Material',item:m.name,on_hand:m.onHand,unit:m.unit,coverage_days:m.coverageDays,status:m.status})),...s.orders.map(o=>({entity_type:'Customer order',item:o.id,customer:o.customer,quantity:o.units,due:o.due,at_risk:o.atRisk?'Yes':'No',status:o.status}))]:[{entity_type:'Summary',on_time_delivery_percent:snapshot().delivery,supplier_quality_percent:100-snapshot().supplier,status:'Illustrative summary'}]}
 if(f.type==='maintenance')data=assets.map((_,index)=>{const a=assetFor(fi,index),j=jobFor(index,fi),actual=record?.assets?.some(x=>x.index===index);return {asset:a.id,name:a.name,area:a.area,health_percent:a.health,condition:a.reading,work_order:j.id||'',technician:peopleFor(fi).find(p=>p.id===j.assignee)?.name||'Not assigned',status:j.status,...(!actual?{source:'Illustrative',source_name:'Demonstration',observed_at:''}:{})}});
 if(f.type==='batches')data=scopedBatches(true).map(b=>({batch:b.id,line:b.line+1,product:b.product,stage:batchStages[b.stage],progress_percent:b.progress,status:b.status}));
 if(f.type==='alarms')data=visibleAlarms().map(a=>({alarm:a.id,area:a.area,asset:a.asset,severity:a.severity,impact:a.impact,event_time:a.time,status:alarmStatus(a.id)}));
 if(f.type==='workforce')data=peopleFor(fi).map(p=>({technician:p.id,name:p.name,role:p.role,skills:p.skills.join(', '),qualification_expiry:p.expiry,status:p.valid?'Current':'Expired'}));
 if(f.type==='quality'){if(record?.quality){const q=record.quality;data=(q.pat||[]).map(m=>({measure:m.name,value:m.value,unit:m.unit,minimum:m.min,maximum:m.max,status:m.value>=m.min&&m.value<=m.max?'Within range':'Review'}));if(q.cip){const c=q.cip;data.push({measure:'CIP · '+c.asset+' · '+c.phase,value:c.temperature,unit:'°C',minimum:c.limits.temperatureMin,maximum:c.limits.temperatureMax,status:c.status},{measure:'CIP flow',value:c.flow,unit:'m³/h',minimum:c.limits.flowMin,status:c.flow>=c.limits.flowMin?'Within range':'Review'},{measure:'CIP conductivity',value:c.conductivity,unit:'mS/cm',maximum:c.limits.conductivityMax,status:c.conductivity<=c.limits.conductivityMax?'Within range':'Review'})}}else data=[{measure:'First-pass quality summary',value:snapshot().quality,unit:'%',status:'Illustrative summary'}]}
 if(f.type==='business')data=Object.entries(record?.business||snapshot()).map(([measure,value])=>({measure,value,unit:({cost:'EGP k',downtime:'hours',energy:'EGP/unit',legal:'open cases'})[measure]||'%',status:supplied?'Source snapshot':'Illustrative snapshot'}));
 if(f.type==='sustainability'){if(record?.sustainability){const s=record.sustainability;data=s.labels.map((label,i)=>({interval:label,energy_mwh:s.energy[i],energy_cost_egp_per_unit:s.energyCost[i],water_reuse_percent:s.waterReuse[i],emissions_tco2e:s.emissions[i],waste_recovery_percent:s.wasteRecovery[i],status:'Source snapshot'}))}else data=[{energy_cost_egp_per_unit:snapshot().energy,water_reuse_percent:snapshot().reuse,status:'Illustrative summary'}]}
 rows.push(...data.map(row=>({...meta,...row})))}}finally{state.factory=oldFactory;$('#period').value=oldPeriod}return rows}
function filteredReportRows(){const f=reportSelection(),q=f.search.trim().toLowerCase();return collectReportRows().filter(r=>(f.status==='All'||r.status===f.status)&&(f.source==='All'||r.source===f.source)&&(!q||Object.values(r).some(v=>String(v??'').toLowerCase().includes(q))))}
function reportColumns(rows){return [...new Set(rows.flatMap(r=>Object.keys(r)))]}
function setReportFilter(key,value){if(!Object.hasOwn(reportFilters,key))return;if(key==='factory')value=Number(value);if(key==='type'&&!reportTypes[value])return;if(key==='factory'&&(!Number.isInteger(value)||value< -1||value>=factories.length))return;reportFilters[key]=value;if(['factory','type','period','source'].includes(key))reportFilters.status='All';render();if(key==='search'){const input=$('#report-search');input?.focus();input?.setSelectionRange?.(value.length,value.length)}}
function resetReportFilters(){Object.assign(reportFilters,{factory:state.factory,type:'production',period:$('#period').value,status:'All',source:'All',search:''});render()}
function reportOptions(values,current){return values.map(([value,label])=>`<option value="${escapeHTML(value)}" ${String(current)===String(value)?'selected':''}>${escapeHTML(label)}</option>`).join('')}
function reportsView(){const f=reportSelection(),all=collectReportRows(),rows=filteredReportRows(),columns=reportColumns(rows.length?rows:all),statuses=[...new Set(all.map(r=>r.status).filter(Boolean))].sort();return `<section class="panel report-workspace"><div class="panelhead"><div><h2>Reports & exports</h2><small>Preview and export the same filtered records, with factory and data-source provenance.</small></div><div class="actions"><button onclick="exportFilteredReport('csv')" ${rows.length?'':'disabled'}>Download CSV</button><button onclick="exportFilteredReport('json')" ${rows.length?'':'disabled'}>Download JSON</button><button onclick="printFilteredReport()" ${rows.length?'':'disabled'}>Print / Save PDF</button></div></div><div class="report-filters"><label>Factory<select onchange="setReportFilter('factory',this.value)">${reportOptions([[-1,'All factories'],...factories.map((v,i)=>[i,v.name])],f.factory)}</select></label><label>Report type<select onchange="setReportFilter('type',this.value)">${reportOptions(Object.entries(reportTypes),f.type)}</select></label><label>Period<select onchange="setReportFilter('period',this.value)">${reportOptions(['Today','This week','This month'].map(v=>[v,v]),f.period)}</select></label><label>Status<select onchange="setReportFilter('status',this.value)">${reportOptions(['All',...statuses].map(v=>[v,v]),f.status)}</select></label><label>Data source<select onchange="setReportFilter('source',this.value)">${reportOptions(['All','Illustrative','Imported','Gateway'].map(v=>[v,v]),f.source)}</select></label><label>Search<input id="report-search" type="search" value="${escapeHTML(f.search)}" placeholder="Asset, order, person…" oninput="setReportFilter('search',this.value)"></label>${opButton('Reset','resetReportFilters()')}</div><div class="report-summary"><span><strong>${rows.length}</strong> matching records · ${new Set(rows.map(r=>r.factory)).size} factories · ${escapeHTML(f.period)}</span><span>Preview pages are for viewing; exports include <strong>all ${rows.length}</strong> matching records.</span></div><div class="table-scroll report-table"><table><thead><tr>${columns.map(k=>`<th>${escapeHTML(k.replaceAll('_',' '))}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${columns.map(k=>`<td title="${escapeHTML(r[k]??'')}">${escapeHTML(r[k]??'—')}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${Math.max(1,columns.length)}">No records match these filters. Adjust the status, source or search.</td></tr>`}</tbody></table></div><div class="report-notice">Period selects the available period snapshot; it does not reconstruct historical data. Missing source sections remain labeled Illustrative. PDF opens the browser print dialog; choose Save as PDF.</div></section>`}
function exportFilteredReport(format){const rows=filteredReportRows();if(!rows.length)return;const f=reportSelection(),stamp=new Date().toISOString(),name='life-science-'+f.type+'-'+f.period.toLowerCase().replaceAll(' ','-');if(format==='json'){downloadable(name+'.json',JSON.stringify({generatedAt:stamp,filters:f,count:rows.length,rows},null,2),'application/json');return}const keys=reportColumns(rows),cell=value=>{let text=String(value??'');if(typeof value==='string'&&/^[\s]*[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'};const csv=[keys,...rows.map(row=>keys.map(k=>row[k]))].map(row=>row.map(cell).join(',')).join('\r\n');downloadable(name+'.csv','\ufeff'+csv)}
function printFilteredReport(){const rows=filteredReportRows();if(!rows.length)return;const f=reportSelection(),keys=reportColumns(rows),factory=f.factory<0?'All factories':factories[f.factory].name;printHTML(`<!doctype html><html><head><meta charset="utf-8"><title>Life Science · ${escapeHTML(reportTypes[f.type])}</title><style>@page{size:A4 landscape;margin:12mm}body{font:10px Arial,sans-serif;color:#25343b}h1{font-size:22px}p{line-height:1.5}table{border-collapse:collapse;width:100%;table-layout:fixed}th,td{border:1px solid #ccd5d8;padding:5px;text-align:left;overflow-wrap:anywhere}th{background:#e8f4ef;text-transform:capitalize}thead{display:table-header-group}tr{break-inside:avoid}footer{margin-top:12px;color:#58656a}</style></head><body><h1>Life Science · ${escapeHTML(reportTypes[f.type])}</h1><p>Factory: ${escapeHTML(factory)} · Period: ${escapeHTML(f.period)}<br>Status: ${escapeHTML(f.status)} · Source: ${escapeHTML(f.source)} · Search: ${escapeHTML(f.search||'None')}<br>${rows.length} matching records · Generated ${escapeHTML(new Date().toISOString())}</p><table><thead><tr>${keys.map(k=>`<th>${escapeHTML(k.replaceAll('_',' '))}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${keys.map(k=>`<td>${escapeHTML(row[k]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table><footer>Illustrative and supplied records are identified in the Source column. Imported records and period snapshots are not independently verified production records.</footer></body></html>`)}
if(!tabs.includes('Reports'))tabs.push('Reports');
const genericBeforeReports=generic;generic=function(){return state.tab==='Reports'?reportsView():genericBeforeReports()};
const renderBeforeReports=render;render=function(){document.body.classList.toggle('reports-mode',state.tab==='Reports');renderBeforeReports()};
render();
